function findSubsequences(nums) {
  const n = nums.length;
  const found = new Map();
  for (let mask = 0; mask < (1 << n); mask++) {
    const picked = [];
    for (let j = 0; j < n; j++) if (mask & (1 << j)) picked.push(nums[j]);
    if (picked.length < 2) continue;
    let ok = true;
    for (let j = 1; j < picked.length; j++) if (picked[j] < picked[j - 1]) ok = false;
    if (ok) found.set(picked.join(','), picked);
  }
  return [...found.values()];
}

