function generate(rand, size) {
  if (size === 'large') {
    return [Array.from({ length: 15 }, () => Math.floor(rand() * 201) - 100)];
  }
  const n = 1 + Math.floor(rand() * 9);
  const span = 1 + Math.floor(rand() * 4);
  return [Array.from({ length: n }, () => Math.floor(rand() * (2 * span + 1)) - span)];
}
